using System;namespace Recovered.Gameplay {public static class PtlRuntimeThreadCPU {static Func<SoundSetupImage,uint,uint[],uint> Route(Func<SoundSetupImage,uint,uint[],uint> leaf){Func<SoundSetupImage,uint,uint[],uint> route=null;route=delegate(SoundSetupImage image,uint address,uint[] args){if(address==0x751190||address==0x7510d8||address==0x7511d0)return leaf(image,image.Word(address),args);if(address==0x6f0395)return PtlThreadNoExit.Get(image,route);if(address==0x6f024e)return PtlThreadCodec.Getter(image,route);if(address==0x6f01bc)return PtlThreadCodec.Decode(image,args[0],route);if(address==0x6f0145)return PtlThreadEncoder.Encode(image,args[0],route);if(address==0x6f00d9)return PtlRuntimeCapability.Supported(image,route);if(address==0x6f02d6)return PtlThreadInitializedCPU.Initialize(image,args[0],args[1],route);if(address==0x6f07af)return PtlRuntimeEncodedCPU.Calloc(image,args[0],args[1],route);if(address==0x6e7633){PtlRuntimeEncodedCPU.Free(image,args[0],route);return 0;}if(address==0x6f188a)return PtlRuntimeEncodedCPU.Enter(image,args[0],route);if(address==0x6f179a)return PtlRuntimeEncodedCPU.Leave(image,args[0],route);return leaf(image,address,args);};return route;}public static uint Acquire(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlThreadNoExit.Get(m,Route(leaf));}public static uint Required(SoundSetupImage m,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlThreadState.Get(m,Route(leaf));}public static uint Malloc(SoundSetupImage m,uint size,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlRuntimeEncodedCPU.Malloc(m,size,Route(leaf));}public static uint Calloc(SoundSetupImage m,uint count,uint size,Func<SoundSetupImage,uint,uint[],uint> leaf){return PtlRuntimeEncodedCPU.Calloc(m,count,size,Route(leaf));}public static void Free(SoundSetupImage m,uint pointer,Func<SoundSetupImage,uint,uint[],uint> leaf){PtlRuntimeEncodedCPU.Free(m,pointer,Route(leaf));}}}